ST.xhtml:p:
IF g_nLaserBrand=6 THEN(*激关器品牌6是新添加的IPG-QCW激光器，与IPG原理一样*)
  g_nLaserBrand :=0;
  g_bQCWType := TRUE;
ELSE
  g_bQCWType := FALSE;
END_IF;
g_fXYUCurrentSpeed_ABS := g_fiXYUCurrentSpeed;
IF g_fXYUCurrentSpeed_ABS <=0.0 THEN
 g_fXYUCurrentSpeed_ABS :=0.0; 
END_IF;
IF g_bChangeSecondFlyAndPowerCutCommunicationCycle THEN
  fActualCommunicationCycle := g_fSecondCommunicationCycle;
ELSE
  fActualCommunicationCycle := g_fCommunicationCycle;
END_IF; 
SpeedBuffer(InValue := g_fXYUCurrentSpeed_ABS,
InCycle := fActualCommunicationCycle,
OutCycleValue => g_fiXYCurrentSpeedBuff);(*对切割命令速度进行延时通讯周期时间处理*)
g_foCurrentSpeed := g_fiXYCurrentSpeedBuff;

AngleBuffer(InValue := g_diRotateAxisMachineCoordinate,
InCycle := fActualCommunicationCycle,
OutCycleValue => g_dPendulumAngleSfterFilter);
SlowStartAndEndCutListen();
LaserPowerOnControl();(*激光上电*)
LaserCutting();(*激光出光*)
LaserDot();(*激光打点*)
LaserRedLight();(*激光红点*)  
IF NOT g_bLaserPowerOnEnable THEN
  g_noULaserPowerValue := 0;
  g_noUPwmFreq :=0;
  g_noUPwmDuty :=0;
  g_boLaserEnable := FALSE;
END_IF;
